(function(w){w.HOMEWORK_SET_DATA=w.HOMEWORK_SET_DATA||{};w.HOMEWORK_SET_DATA["unit31-trap-c1-advanced-3"]={"id":"unit31-trap-c1-advanced-3","unitId":"3-1","chapterIds":["3-1"],"unitType":"advanced","group":"3-1단원 · 선지 변형 유형 · 반의어","name":"심화 3","level":"심화","revision":1,"originPage":"unit31","shuffleQuestions":true,"timedMode":"question","isTypePractice":true,"practiceMode":"trap","practiceCategory":"반의어","parts":[{"name":"U31-P13-02-S1 · 반의어","items":[{"paragraphCount":1,"readingLabel":"13문단","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 13문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 13문단]\n한편, 프롬은 성숙한 사랑에는 다음 세 가지 요소가 있다고 하였다. 첫째로 사랑하는 자의 생명과 성장에 대한 ‘적극적인 관심’이다. 만일 어떤 사람이 자기는 꽃을 사랑한다고 말하였는데 꽃에 물을 주는 것을 잊고 있다면, 우리는 그 사람이 꽃을 사랑한다는 말을 믿지 않을 것이다. 이러한 보호와 관심에는 사랑의 두 번째 요소인 ‘책임’이 포함되어 있다. 책임은 상대의 요구에 응답할 준비가 되어 있다는 것이며, 더불어 다른 사람의 잘잘못을 함께하려는 것이다. 세 번째는 ‘존경’이다. 존경한다는 것은 어떤 사람의 독특한 개성을 통찰하고 존중하는 것이다. 존경은 다른 사람이 그 자신으로서 성장하고 발달하기를 바라는 관심이다. 존경이 결여되면, 책임은 쉽게 상대방을 지배하고 소유하려는 욕망으로 전락한다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["반의어"],"why":"책임은 상대의 필요를 외면하지 않고 응하려는 태도다. 상대의 잘잘못도 함께하려는 뜻을 포함한다.\n근거: “책임은 상대의 요구에 응답할 준비가 되어 있다는 것이며, 더불어 다른 사람의 잘잘못을 함께하려는 것이다.”\n13문단에서 확인할 수 있어요.","evidence":{"title":"책임은 요구에 응답할 준비이다.","statement":"책임을 지는 사람은 상대가 필요로 하는 것에 응할 준비가 되어 있다. 상대가 잘했을 때도, 잘못했을 때도 함께하려 한다.","explanation":"책임은 상대의 필요를 외면하지 않고 응하려는 태도다. 상대의 잘잘못도 함께하려는 뜻을 포함한다.\n근거: “책임은 상대의 요구에 응답할 준비가 되어 있다는 것이며, 더불어 다른 사람의 잘잘못을 함께하려는 것이다.”\n13문단에서 확인할 수 있어요.","valid":["R13:5"],"sources":[{"id":"R13","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"13문단","sentences":[{"id":"R13:1","text":"한편, 프롬은 성숙한 사랑에는 다음 세 가지 요소가 있다고 하였다.","paragraph":0,"memberIds":["R13:1"],"topic":"또 프롬은 성숙한 사랑에 세 가지 요소가 있다고 했다."},{"id":"R13:2","text":"첫째로 사랑하는 자의 생명과 성장에 대한 ‘적극적인 관심’이다.","paragraph":0,"memberIds":["R13:2"],"topic":"첫째는 '적극적인 관심'이다. 내가 사랑하는 상대가 살아가고 자라는 것(생명과 성장)에 적극적으로 마음을 쓰는 것이다."},{"id":"R13:3","text":"만일 어떤 사람이 자기는 꽃을 사랑한다고 말하였는데 꽃에 물을 주는 것을 잊고 있다면, 우리는 그 사람이 꽃을 사랑한다는 말을 믿지 않을 것이다.","paragraph":0,"memberIds":["R13:3"],"topic":"어떤 사람이 꽃을 사랑한다고 말하면서, 꽃에 물 주는 것을 잊고 있다고 해 보자. 우리는 그 사람이 꽃을 사랑한다는 말을 믿지 않을 것이다."},{"id":"R13:4","text":"이러한 보호와 관심에는 사랑의 두 번째 요소인 ‘책임’이 포함되어 있다.","paragraph":0,"memberIds":["R13:4"],"topic":"이렇게 보호하고 관심을 갖는 것 안에는 사랑의 두 번째 요소인 '책임'이 들어 있다."},{"id":"R13:5","text":"책임은 상대의 요구에 응답할 준비가 되어 있다는 것이며, 더불어 다른 사람의 잘잘못을 함께하려는 것이다.","paragraph":0,"memberIds":["R13:5"],"topic":"책임은 상대가 무언가를 바랄(요구할) 때 응답할 준비가 되어 있는 것이다. 그리고 상대가 잘한 일도 잘못한 일도 함께하려는 것이다."},{"id":"R13:6","text":"세 번째는 ‘존경’이다.","paragraph":0,"memberIds":["R13:6"],"topic":"세 번째는 '존경'이다."},{"id":"R13:7","text":"존경한다는 것은 어떤 사람의 독특한 개성을 통찰하고 존중하는 것이다.","paragraph":0,"memberIds":["R13:7"],"topic":"존경한다는 것은 그 사람만의 독특한 개성을 꿰뚫어 보고(통찰하고) 존중하는 것이다."},{"id":"R13:8","text":"존경은 다른 사람이 그 자신으로서 성장하고 발달하기를 바라는 관심이다.","paragraph":0,"memberIds":["R13:8"],"topic":"존경은 상대가 그 사람 자신으로서(그 사람답게) 자라고 발전하기를 바라는 관심이다."},{"id":"R13:9","text":"존경이 결여되면, 책임은 쉽게 상대방을 지배하고 소유하려는 욕망으로 전락한다.","paragraph":0,"memberIds":["R13:9"],"topic":"존경이 빠지면(결여되면), 책임은 쉽게 상대를 내 마음대로 하고 내 것으로 삼으려는 욕심으로 떨어진다(전락한다)."}]}]},"id":"U31-P13-02-S1","type":"mc","sent":"13문단의 내용과 맞는 설명은?","options":["책임을 지는 사람은 상대가 필요로 하는 것을 외면한다. 상대가 잘했든 잘못했든 함께하려 하지 않는다.","상대에게 적극적으로 관심을 갖는 사람은 '사랑한다'고 말만 하면 된다. 실제로 돌볼 필요는 없다.","상대를 존경하는 사람은 상대만의 개성을 인정하지 않고 없애려 한다.","책임을 지는 사람은 상대가 필요로 하는 것에 응할 준비가 되어 있다. 상대가 잘했을 때도, 잘못했을 때도 함께하려 한다.","상대를 존경하는 사람은 상대가 나와 똑같은 모습으로 성장하기를 바란다."],"answer":"책임을 지는 사람은 상대가 필요로 하는 것에 응할 준비가 되어 있다. 상대가 잘했을 때도, 잘못했을 때도 함께하려 한다.","choiceReviews":{"책임을 지는 사람은 상대가 필요로 하는 것에 응할 준비가 되어 있다. 상대가 잘했을 때도, 잘못했을 때도 함께하려 한다.":{"reason":"책임은 상대의 필요를 외면하지 않고 응하려는 태도다. 상대의 잘잘못도 함께하려는 뜻을 포함한다.\n근거: “책임은 상대의 요구에 응답할 준비가 되어 있다는 것이며, 더불어 다른 사람의 잘잘못을 함께하려는 것이다.”\n13문단에서 확인할 수 있어요.","edits":[]},"책임을 지는 사람은 상대가 필요로 하는 것을 외면한다. 상대가 잘했든 잘못했든 함께하려 하지 않는다.":{"reason":"바르게 고치면: 책임을 지는 사람은 상대가 필요로 하는 것에 응할 준비가 되어 있다. 상대가 잘했을 때도, 잘못했을 때도 함께하려 한다.\n책임은 상대의 필요를 외면하지 않고 응하려는 태도다. 상대의 잘잘못도 함께하려는 뜻을 포함한다.\n근거: “책임은 상대의 요구에 응답할 준비가 되어 있다는 것이며, 더불어 다른 사람의 잘잘못을 함께하려는 것이다.”\n13문단에서 확인할 수 있어요.","edits":[{"start":22,"end":31,"before":"것을 외면한다. ","after":"것에 응할 준비가 되어 있다. "},{"start":35,"end":44,"before":"잘했든 잘못했든 ","after":"잘했을 때도, 잘못했을 때도 "},{"start":49,"end":56,"before":"하지 않는다.","after":"한다."}]},"상대에게 적극적으로 관심을 갖는 사람은 '사랑한다'고 말만 하면 된다. 실제로 돌볼 필요는 없다.":{"reason":"바르게 고치면: 상대에게 적극적으로 관심을 갖는 사람은 상대가 잘 살아가고 성장하도록 실제로 돌본다.\n상대에게 적극적으로 관심을 갖는 사람은 상대가 잘 살아가고 성장하도록 실제로 돌본다.\n근거: “첫째로 사랑하는 자의 생명과 성장에 대한 ‘적극적인 관심’이다.” “만일 어떤 사람이 자기는 꽃을 사랑한다고 말하였는데 꽃에 물을 주는 것을 잊고 있다면, 우리는 그 사람이 꽃을 사랑한다는 말을 믿지 않을 것이다.”\n13문단에서 확인할 수 있어요.","edits":[{"start":22,"end":40,"before":"'사랑한다'고 말만 하면 된다. ","after":"상대가 잘 살아가고 성장하도록 "},{"start":44,"end":54,"before":"돌볼 필요는 없다.","after":"돌본다."}]},"상대를 존경하는 사람은 상대만의 개성을 인정하지 않고 없애려 한다.":{"reason":"바르게 고치면: 상대를 존경하는 사람은 상대만의 개성을 깊이 이해하고 존중한다.\n상대를 존경하는 사람은 상대만의 개성을 깊이 이해하고 존중한다.\n근거: “존경한다는 것은 어떤 사람의 독특한 개성을 통찰하고 존중하는 것이다.”\n13문단에서 확인할 수 있어요.","edits":[{"start":22,"end":37,"before":"인정하지 않고 없애려 한다.","after":"깊이 이해하고 존중한다."}]},"상대를 존경하는 사람은 상대가 나와 똑같은 모습으로 성장하기를 바란다.":{"reason":"바르게 고치면: 상대를 존경하는 사람은 상대가 자기 개성을 지키며 성장하기를 바란다.\n상대를 존경하는 사람은 상대가 자기 개성을 지키며 성장하기를 바란다.\n근거: “존경은 다른 사람이 그 자신으로서 성장하고 발달하기를 바라는 관심이다.”\n13문단에서 확인할 수 있어요.","edits":[{"start":17,"end":29,"before":"나와 똑같은 모습으로 ","after":"자기 개성을 지키며 "}]}},"pageSpecificReasons":true,"requiresEvidence":true,"editorSourceVersion":"7b3208064a4d0d6af8b4a45959296ec5177787755ba720a3bfe0f97aba41e448"}]},{"name":"U31-P13-03-S1 · 반의어","items":[{"paragraphCount":1,"readingLabel":"13문단","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 13문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 13문단]\n한편, 프롬은 성숙한 사랑에는 다음 세 가지 요소가 있다고 하였다. 첫째로 사랑하는 자의 생명과 성장에 대한 ‘적극적인 관심’이다. 만일 어떤 사람이 자기는 꽃을 사랑한다고 말하였는데 꽃에 물을 주는 것을 잊고 있다면, 우리는 그 사람이 꽃을 사랑한다는 말을 믿지 않을 것이다. 이러한 보호와 관심에는 사랑의 두 번째 요소인 ‘책임’이 포함되어 있다. 책임은 상대의 요구에 응답할 준비가 되어 있다는 것이며, 더불어 다른 사람의 잘잘못을 함께하려는 것이다. 세 번째는 ‘존경’이다. 존경한다는 것은 어떤 사람의 독특한 개성을 통찰하고 존중하는 것이다. 존경은 다른 사람이 그 자신으로서 성장하고 발달하기를 바라는 관심이다. 존경이 결여되면, 책임은 쉽게 상대방을 지배하고 소유하려는 욕망으로 전락한다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["반의어"],"why":"상대를 존경하는 사람은 상대만의 개성을 깊이 이해하고 존중한다.\n근거: “존경한다는 것은 어떤 사람의 독특한 개성을 통찰하고 존중하는 것이다.”\n13문단에서 확인할 수 있어요.","evidence":{"title":"존경은 독특한 개성을 존중한다.","statement":"상대를 존경하는 사람은 상대만의 개성을 깊이 이해하고 존중한다.","explanation":"상대를 존경하는 사람은 상대만의 개성을 깊이 이해하고 존중한다.\n근거: “존경한다는 것은 어떤 사람의 독특한 개성을 통찰하고 존중하는 것이다.”\n13문단에서 확인할 수 있어요.","valid":["R13:7"],"sources":[{"id":"R13","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"13문단","sentences":[{"id":"R13:1","text":"한편, 프롬은 성숙한 사랑에는 다음 세 가지 요소가 있다고 하였다.","paragraph":0,"memberIds":["R13:1"],"topic":"또 프롬은 성숙한 사랑에 세 가지 요소가 있다고 했다."},{"id":"R13:2","text":"첫째로 사랑하는 자의 생명과 성장에 대한 ‘적극적인 관심’이다.","paragraph":0,"memberIds":["R13:2"],"topic":"첫째는 '적극적인 관심'이다. 내가 사랑하는 상대가 살아가고 자라는 것(생명과 성장)에 적극적으로 마음을 쓰는 것이다."},{"id":"R13:3","text":"만일 어떤 사람이 자기는 꽃을 사랑한다고 말하였는데 꽃에 물을 주는 것을 잊고 있다면, 우리는 그 사람이 꽃을 사랑한다는 말을 믿지 않을 것이다.","paragraph":0,"memberIds":["R13:3"],"topic":"어떤 사람이 꽃을 사랑한다고 말하면서, 꽃에 물 주는 것을 잊고 있다고 해 보자. 우리는 그 사람이 꽃을 사랑한다는 말을 믿지 않을 것이다."},{"id":"R13:4","text":"이러한 보호와 관심에는 사랑의 두 번째 요소인 ‘책임’이 포함되어 있다.","paragraph":0,"memberIds":["R13:4"],"topic":"이렇게 보호하고 관심을 갖는 것 안에는 사랑의 두 번째 요소인 '책임'이 들어 있다."},{"id":"R13:5","text":"책임은 상대의 요구에 응답할 준비가 되어 있다는 것이며, 더불어 다른 사람의 잘잘못을 함께하려는 것이다.","paragraph":0,"memberIds":["R13:5"],"topic":"책임은 상대가 무언가를 바랄(요구할) 때 응답할 준비가 되어 있는 것이다. 그리고 상대가 잘한 일도 잘못한 일도 함께하려는 것이다."},{"id":"R13:6","text":"세 번째는 ‘존경’이다.","paragraph":0,"memberIds":["R13:6"],"topic":"세 번째는 '존경'이다."},{"id":"R13:7","text":"존경한다는 것은 어떤 사람의 독특한 개성을 통찰하고 존중하는 것이다.","paragraph":0,"memberIds":["R13:7"],"topic":"존경한다는 것은 그 사람만의 독특한 개성을 꿰뚫어 보고(통찰하고) 존중하는 것이다."},{"id":"R13:8","text":"존경은 다른 사람이 그 자신으로서 성장하고 발달하기를 바라는 관심이다.","paragraph":0,"memberIds":["R13:8"],"topic":"존경은 상대가 그 사람 자신으로서(그 사람답게) 자라고 발전하기를 바라는 관심이다."},{"id":"R13:9","text":"존경이 결여되면, 책임은 쉽게 상대방을 지배하고 소유하려는 욕망으로 전락한다.","paragraph":0,"memberIds":["R13:9"],"topic":"존경이 빠지면(결여되면), 책임은 쉽게 상대를 내 마음대로 하고 내 것으로 삼으려는 욕심으로 떨어진다(전락한다)."}]}]},"id":"U31-P13-03-S1","type":"mc","sent":"13문단의 내용과 맞는 설명은?","options":["상대를 존경하는 사람은 상대만의 개성을 인정하지 않고 없애려 한다.","상대에게 적극적으로 관심을 갖는 사람은 '사랑한다'고 말만 하면 된다. 실제로 돌볼 필요는 없다.","책임을 지는 사람은 상대가 필요로 하는 것을 외면한다. 상대가 잘했든 잘못했든 함께하려 하지 않는다.","상대를 존경하는 사람은 상대가 나와 똑같은 모습으로 성장하기를 바란다.","상대를 존경하는 사람은 상대만의 개성을 깊이 이해하고 존중한다."],"answer":"상대를 존경하는 사람은 상대만의 개성을 깊이 이해하고 존중한다.","choiceReviews":{"상대를 존경하는 사람은 상대만의 개성을 깊이 이해하고 존중한다.":{"reason":"상대를 존경하는 사람은 상대만의 개성을 깊이 이해하고 존중한다.\n근거: “존경한다는 것은 어떤 사람의 독특한 개성을 통찰하고 존중하는 것이다.”\n13문단에서 확인할 수 있어요.","edits":[]},"상대를 존경하는 사람은 상대만의 개성을 인정하지 않고 없애려 한다.":{"reason":"바르게 고치면: 상대를 존경하는 사람은 상대만의 개성을 깊이 이해하고 존중한다.\n상대를 존경하는 사람은 상대만의 개성을 깊이 이해하고 존중한다.\n근거: “존경한다는 것은 어떤 사람의 독특한 개성을 통찰하고 존중하는 것이다.”\n13문단에서 확인할 수 있어요.","edits":[{"start":22,"end":37,"before":"인정하지 않고 없애려 한다.","after":"깊이 이해하고 존중한다."}]},"상대에게 적극적으로 관심을 갖는 사람은 '사랑한다'고 말만 하면 된다. 실제로 돌볼 필요는 없다.":{"reason":"바르게 고치면: 상대에게 적극적으로 관심을 갖는 사람은 상대가 잘 살아가고 성장하도록 실제로 돌본다.\n상대에게 적극적으로 관심을 갖는 사람은 상대가 잘 살아가고 성장하도록 실제로 돌본다.\n근거: “첫째로 사랑하는 자의 생명과 성장에 대한 ‘적극적인 관심’이다.” “만일 어떤 사람이 자기는 꽃을 사랑한다고 말하였는데 꽃에 물을 주는 것을 잊고 있다면, 우리는 그 사람이 꽃을 사랑한다는 말을 믿지 않을 것이다.”\n13문단에서 확인할 수 있어요.","edits":[{"start":22,"end":40,"before":"'사랑한다'고 말만 하면 된다. ","after":"상대가 잘 살아가고 성장하도록 "},{"start":44,"end":54,"before":"돌볼 필요는 없다.","after":"돌본다."}]},"책임을 지는 사람은 상대가 필요로 하는 것을 외면한다. 상대가 잘했든 잘못했든 함께하려 하지 않는다.":{"reason":"바르게 고치면: 책임을 지는 사람은 상대가 필요로 하는 것에 응할 준비가 되어 있다. 상대가 잘했을 때도, 잘못했을 때도 함께하려 한다.\n책임은 상대의 필요를 외면하지 않고 응하려는 태도다. 상대의 잘잘못도 함께하려는 뜻을 포함한다.\n근거: “책임은 상대의 요구에 응답할 준비가 되어 있다는 것이며, 더불어 다른 사람의 잘잘못을 함께하려는 것이다.”\n13문단에서 확인할 수 있어요.","edits":[{"start":22,"end":31,"before":"것을 외면한다. ","after":"것에 응할 준비가 되어 있다. "},{"start":35,"end":44,"before":"잘했든 잘못했든 ","after":"잘했을 때도, 잘못했을 때도 "},{"start":49,"end":56,"before":"하지 않는다.","after":"한다."}]},"상대를 존경하는 사람은 상대가 나와 똑같은 모습으로 성장하기를 바란다.":{"reason":"바르게 고치면: 상대를 존경하는 사람은 상대가 자기 개성을 지키며 성장하기를 바란다.\n상대를 존경하는 사람은 상대가 자기 개성을 지키며 성장하기를 바란다.\n근거: “존경은 다른 사람이 그 자신으로서 성장하고 발달하기를 바라는 관심이다.”\n13문단에서 확인할 수 있어요.","edits":[{"start":17,"end":29,"before":"나와 똑같은 모습으로 ","after":"자기 개성을 지키며 "}]}},"pageSpecificReasons":true,"requiresEvidence":true,"editorSourceVersion":"aac79a3882d063107508b7669596cd2c26b915e980a7d35803050a98b50b838b"}]},{"name":"U31-P14-05-S1 · 반의어","items":[{"paragraphCount":1,"readingLabel":"14문단","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 14문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 14문단]\n나아가 성숙한 사랑은 결코 한 사람에게 제한되지 않는다. 예를 들어 두 연인이 진정으로 사랑을 하고 부모가 진정으로 자녀를 사랑할 때, 그들은 그들 외의 다른 사람들에게 무관심하게 되는 것이 아니다. 그들은 자신들만의 이기적인 사랑을 추구하지 않는다. 사랑하는 두 연인은 자신들의 사랑이 다른 사람들의 행복에 기여하는 것이 되기를 바란다. 그리고 자식을 사랑하는 부모는 자식이 이기적인 인간이 아니라 남을 도울 수 있는 훌륭한 인간이 되기를 바란다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["반의어"],"why":"자식을 사랑하는 부모는 자식이 남을 돕는 사람으로 자라기를 바란다.\n근거: “그리고 자식을 사랑하는 부모는 자식이 이기적인 인간이 아니라 남을 도울 수 있는 훌륭한 인간이 되기를 바란다.”\n14문단에서 확인할 수 있어요.","evidence":{"title":"부모는 남을 돕는 자녀를 바란다.","statement":"자식을 사랑하는 부모는 자식이 남을 돕는 사람으로 자라기를 바란다.","explanation":"자식을 사랑하는 부모는 자식이 남을 돕는 사람으로 자라기를 바란다.\n근거: “그리고 자식을 사랑하는 부모는 자식이 이기적인 인간이 아니라 남을 도울 수 있는 훌륭한 인간이 되기를 바란다.”\n14문단에서 확인할 수 있어요.","valid":["R14:5"],"sources":[{"id":"R14","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"14문단","sentences":[{"id":"R14:1","text":"나아가 성숙한 사랑은 결코 한 사람에게 제한되지 않는다.","paragraph":0,"memberIds":["R14:1"],"topic":"더 나아가 성숙한 사랑은 절대 한 사람에게만 머무르지(제한되지) 않는다."},{"id":"R14:2","text":"예를 들어 두 연인이 진정으로 사랑을 하고 부모가 진정으로 자녀를 사랑할 때, 그들은 그들 외의 다른 사람들에게 무관심하게 되는 것이 아니다.","paragraph":0,"memberIds":["R14:2"],"topic":"예를 들어 두 연인이 진짜로 사랑하고, 부모가 진짜로 자녀를 사랑한다고 하자. 그렇다고 그들이 다른 사람들에게 관심을 끊는(무관심해지는) 것은 아니다."},{"id":"R14:3","text":"그들은 자신들만의 이기적인 사랑을 추구하지 않는다.","paragraph":0,"memberIds":["R14:3"],"topic":"그들은 자기들끼리만 챙기는 이기적인 사랑을 바라지(추구하지) 않는다."},{"id":"R14:4","text":"사랑하는 두 연인은 자신들의 사랑이 다른 사람들의 행복에 기여하는 것이 되기를 바란다.","paragraph":0,"memberIds":["R14:4"],"topic":"사랑하는 두 연인은 자기들의 사랑이 다른 사람들의 행복에도 도움이 되기를(기여하기를) 바란다."},{"id":"R14:5","text":"그리고 자식을 사랑하는 부모는 자식이 이기적인 인간이 아니라 남을 도울 수 있는 훌륭한 인간이 되기를 바란다.","paragraph":0,"memberIds":["R14:5"],"topic":"그리고 자식을 사랑하는 부모는 자식이 이기적인 사람이 아니라, 남을 도울 수 있는 훌륭한 사람이 되기를 바란다."}]}]},"id":"U31-P14-05-S1","type":"mc","sent":"14문단의 내용과 맞는 설명은?","options":["자식을 사랑하는 부모는 자식이 남을 돕지 않고 자신만 챙기기를 바란다.","성숙한 사랑은 한 사람에게만 머무른다.","자식을 사랑하는 부모는 자식이 남을 돕는 사람으로 자라기를 바란다.","진정으로 사랑하는 연인은 다른 사람들에게 관심을 두지 않는다. 자녀를 진정으로 사랑하는 부모도 마찬가지다.","진정으로 사랑하는 사람들은 자기들만 잘되면 된다고 생각한다."],"answer":"자식을 사랑하는 부모는 자식이 남을 돕는 사람으로 자라기를 바란다.","choiceReviews":{"자식을 사랑하는 부모는 자식이 남을 돕는 사람으로 자라기를 바란다.":{"reason":"자식을 사랑하는 부모는 자식이 남을 돕는 사람으로 자라기를 바란다.\n근거: “그리고 자식을 사랑하는 부모는 자식이 이기적인 인간이 아니라 남을 도울 수 있는 훌륭한 인간이 되기를 바란다.”\n14문단에서 확인할 수 있어요.","edits":[]},"자식을 사랑하는 부모는 자식이 남을 돕지 않고 자신만 챙기기를 바란다.":{"reason":"바르게 고치면: 자식을 사랑하는 부모는 자식이 남을 돕는 사람으로 자라기를 바란다.\n자식을 사랑하는 부모는 자식이 남을 돕는 사람으로 자라기를 바란다.\n근거: “그리고 자식을 사랑하는 부모는 자식이 이기적인 인간이 아니라 남을 도울 수 있는 훌륭한 인간이 되기를 바란다.”\n14문단에서 확인할 수 있어요.","edits":[{"start":20,"end":35,"before":"돕지 않고 자신만 챙기기를 ","after":"돕는 사람으로 자라기를 "}]},"성숙한 사랑은 한 사람에게만 머무른다.":{"reason":"바르게 고치면: 성숙한 사랑은 한 사람에게만 머무르지 않는다.\n성숙한 사랑은 한 사람에게만 머무르지 않는다.\n근거: “나아가 성숙한 사랑은 결코 한 사람에게 제한되지 않는다.”\n14문단에서 확인할 수 있어요.","edits":[{"start":16,"end":21,"before":"머무른다.","after":"머무르지 않는다."}]},"진정으로 사랑하는 연인은 다른 사람들에게 관심을 두지 않는다. 자녀를 진정으로 사랑하는 부모도 마찬가지다.":{"reason":"바르게 고치면: 진정으로 사랑하는 연인은 다른 사람들에게도 관심을 갖는다. 자녀를 진정으로 사랑하는 부모도 마찬가지다.\n진정으로 사랑하는 연인은 다른 사람들에게도 관심을 갖는다. 자녀를 진정으로 사랑하는 부모도 마찬가지다.\n근거: “예를 들어 두 연인이 진정으로 사랑을 하고 부모가 진정으로 자녀를 사랑할 때, 그들은 그들 외의 다른 사람들에게 무관심하게 되는 것이 아니다.”\n14문단에서 확인할 수 있어요.","edits":[{"start":17,"end":23,"before":"사람들에게 ","after":"사람들에게도 "},{"start":27,"end":35,"before":"두지 않는다. ","after":"갖는다. "}]},"진정으로 사랑하는 사람들은 자기들만 잘되면 된다고 생각한다.":{"reason":"바르게 고치면: 진정으로 사랑하는 사람들은 자기들만 잘되면 된다고 생각하지 않는다.\n진정으로 사랑하는 사람들은 자기들만 잘되면 된다고 생각하지 않는다.\n근거: “그들은 자신들만의 이기적인 사랑을 추구하지 않는다.”\n14문단에서 확인할 수 있어요.","edits":[{"start":28,"end":33,"before":"생각한다.","after":"생각하지 않는다."}]}},"pageSpecificReasons":true,"requiresEvidence":true,"editorSourceVersion":"e26b044b732e6ebfa0ad242dd85be30c4e35a8fa75b8da50941a3885b368ff9a"}]}]};})(window);
